  const logo = w >= 66 ? bbsLogo("NIGHT OWL", w) : [center("{b}N I G H T   O W L{n}")];
  const node = center("{d}────────{n}  Node 1 of 1  {d}·{n}  28800 bps  {d}·{n}  always open  {d}────────{n}");
  const link = ([label, url, shown], i, wide = 0) => `   {>url:${url}}[{b}${i + 1}{n}] ${pad(esc(label), 10)}${esc(shown)}${" ".repeat(Math.max(0, wide - shown.length))}{<}`;
