    ELSE() { X.ti = X.line.toks.length; },
    LET() { assign(); }, PRINT, IF, FOR, NEXT, WHILE, WEND, GOSUB, RETURN, ON, READ, RESTORE, DIM, DEF, RUN, LIST, RENUM, ZOMBIE, SLEEP,
    SNAKE() { return game(snakeGame); }, BLOCKS() { return game(blocksGame); },
    INPUT() { return INPUT(false, X.ti - 1); },
    LINE() { const start = X.ti - 1; expKw("INPUT"); return INPUT(true, start); },
